svg=['<svg viewBox="-3 -6 182 174" role="img" aria-label="12栋建筑编号与功能布局"><rect x="0" y="0" width="176" height="160" rx="2" fill="#edf1e7"/>']
for r in sp['roads']:
 pts=' '.join(f'{x},{z}' for x,z in r['path']);svg.append(f'<polyline points="{pts}" fill="none" stroke="#77817f" stroke-width="{r["width"]}"/><polyline points="{pts}" fill="none" stroke="#f6f0d5" stroke-width=".5" stroke-dasharray="2 2"/>')
for h in sp['buildings']:
 svg.append(f'<g><title>{h["id"]} {h["name"]} / {h["floors"]}层 / 地坪Y={h["g"]}</title><rect x="{h["x"]}" y="{h["z"]}" width="{h["w"]}" height="{h["d"]}" rx="1" fill="{colors[h["use"]]}" stroke="#fff" stroke-width=".8"/><text x="{h["x"]+h["w"]/2}" y="{h["z"]+h["d"]/2+1}" text-anchor="middle" font-size="3.3" fill="#243f3b">{h["id"]}</text></g>')
svg.append('<rect x="42" y="75" width="17" height="4" fill="#42675c"/><text x="42" y="72" font-size="3">BUS</text><text x="4" y="5" font-size="4">N ↑</text><text x="1" y="168" font-size="3.3">176 × 160 blocks · Y up · 东 +X / 北 -Z</text></svg>');plan=''.join(svg)
hero='<header><div class="eyebrow">HAF · JAPANESE TOWN / 01</div><h1>日和町<span>十二栋，道路小镇。</span></h1><p>把单栋建筑连成一段可以走进去的街景。住宅、店铺与公共设施共用一条主街，庭院与北侧高差提供变化。</p><div class="badges"><b>原创建造样板</b><b>Java 1.21.1</b><b>'+RUN+'</b><b>2026.10.29</b></div>'+fig(P/'overview.png','12 栋总览','最终 NBT 回读的近似预览；非游戏截图')+'</header>'
contents=[]
contents.append(section(1,'这次实际完成了什么', '<div class="stats"><div><b>12</b><span>独立建筑</span></div><div><b>7 / 2 / 3</b><span>住宅 / 商业 / 公共</span></div><div><b>21</b><span>已布置照明的楼层</span></div><div><b>2–3 格</b><span>北侧住宅相对主街高差</span></div></div><p>公交候车亭、斑马线、路灯、线杆、排水渠、社区公告栏、口袋绿地与停车位已经写入方块。住宅有起居、厨房和睡眠区的初步陈设；公共建筑按用途布置柜台、书架、座位或检查床。</p><p class="note">这是一版街区与外观样板。住宅尚未细分完整卫浴、私密隔间；床、车辆与售货机等是装饰。没有使用生成图片冒充建筑结果。</p>'))
contents.append(section(2,'布局：先形成公共街角', '<div class="two"><div class="map">'+plan+'</div><div><h3>主街串联生活设施</h3><p>主街在中部转折，北支路进入坡上住宅，南支路组织另一组住宅与社区会馆。公交站靠近杂货店与咖啡店，交番和诊所位于同一条主街。</p><h3>留白有用途</h3><p>保留前院、后部服务带、候车区和公园草地。树木与低墙帮助界定地块，部分空地为停留与视线服务。这一版密度仍偏舒展，适合先检查尺度，后续可压缩退距。</p><h3>与旧中式农村案例分开</h3><p>本分支重点是道路街景、住宅入口、店铺前场和轻量公共设施；不直接搬用田埂里的农田配额，也不把日式风格统一替换成寺庙屋顶。</p></div></div>'))
contents.append(section(3,'十二栋清单',table(['编号','用途 / 名称','层数','占地（格）','地坪 Y'],[(h['id'],h['name'],h['floors'],f'{h["w"]} × {h["d"]}',h['g']) for h in sp['buildings']])+'<p class="note">占地是本次原创设计值，未将视频中的尺度当作测绘数据。公交站、停车棚类小设施不计入 12 栋。</p>'))
contents.append(section(4,'街景与灯光',fig(P/'shops.png','商店与候车亭 · 日景')+fig(P/'shops_night.png','相同机位 · 夜景','所有已设计使用楼层保留灯具；灯位与光传播为离线近似')+'<div class="two">'+fig(P/'upper_homes.png','坡上住宅','不同屋顶方向、窗组、庭院边界与入口台阶')+fig(P/'civic.png','公共街角','诊所、交番和公告栏')+'</div>'+fig(P/'south_homes.png','南侧住宅','阳台、院落与排水渠所在街段')+'<p class="note">原版方块材质不等于真实彩色光传播。预览没有资源包纹理，玻璃、链条与灯光均做了简化；最终效果需要在游戏中检查。</p>'))
contents.append(section(5,'随机性：现在执行到了哪一层',table(['层级','本版做法','边界'],[
 ('道路与地块','作者确定转折、支路和功能分组','布局已固定；尚未实现整镇自动换 seed 重排'),
 ('建筑体量','不同尺寸、朝向、楼层与屋顶家族','这些差异是设计选择，不冒称随机采样'),
 ('立面','分层窗组、局部木饰面、阳台与百叶','固定门口、楼板和楼梯；不逐格随机挖洞'),
 ('庭院与植栽','按稳定 ID 分离随机通道，改变树冠边缘、院墙段、蔬菜生长','全部变化可复现；不能占用受保护的路径'),
 ('灯光','低层使用空间均亮灯，门灯与路灯按功能放置','没有用随机熄灯制造空置感'),
 ])+'<p>固定种子 <code>2026102912</code>。同种子复跑的 NBT 字节相同。下一步把随机机制提升到“地块宽深 → 退距 → 建筑家族 → 朝向”，用相同功能配额比较多组结果。</p>'))
contents.append(section(6,'同源图纸与内部样板','<p>主视图与整镇四向预览由最终 NBT 回读。以下技术图同样读取实际方块：整镇分层图按各栋自己的楼层标高展开；剖面、爆炸图与四向立面以 H01 为详细样板，不代表 12 栋都有独立完整施工图。</p><div class="two">'+fig(D/'floor_1.png','各栋首层切层图','橙线为入户路线；方块配色，不是用途热力图')+fig(D/'floor_2.png','各栋二层切层图','单层公共建筑不出现在此图')+'</div><div class="two">'+fig(P/'H01_cut.png','H01 首层剖切','可进入的初步空间与两格宽楼梯')+fig(P/'H01_upper.png','H01 二层剖切','家具和睡眠区目前为示意')+'</div><div class="two">'+fig(D/'section.png','H01 · X=18 剖面','穿过实际楼梯与楼板洞口')+fig(C/'review/previews'/f'{RUN}_exploded'/'exploded.png','H01 · 分层爆炸','水平位置保持；为展示增加竖向间距')+'</div><details><summary>展开 H01 四向等尺度立面</summary><div class="two">'+''.join(fig(D/f'elevation_{f}.png','H01 · '+label+'立面') for f,label in [('south','南'),('east','东'),('north','北'),('west','西')])+'</div></details>'))
contents.append(section(7,'整镇四向与真俯视','<div class="two">'+''.join(fig(P/f'{f}_day.png',lab+' · 日景') for f,lab in [('se','东南'),('sw','西南'),('ne','东北'),('nw','西北')])+'</div><details><summary>展开相同机位四向夜景</summary><div class="two">'+''.join(fig(P/f'{f}_night.png',lab+' · 夜景') for f,lab in [('se','东南'),('sw','西南'),('ne','东北'),('nw','西北')])+'</div></details>'+fig(P/'top_day.png','垂直正交俯视','模型坐标北 -Z；四个斜视相机共用尺度与俯角')))
checks=[('NBT 独立回读','通过',f'{mf["non_air_blocks"]:,} 个非空气方块'),('12 栋与用途配额','通过','7 住宅 + 2 商业 + 3 公共'),('门口、楼梯、入户路线','通过','完整宽度净空；路径承托和相邻高差另查'),('使用楼层灯具 / 地面植物 / 水渠围合','通过','检查实际方块存在与支撑，不代替游戏亮度'),('世界序列化回读','通过',f'{wc["checked_cells"]:,} 格位；差异 {wc["mismatches"]}'),('相同种子复跑','通过','主 NBT 字节哈希一致'),('人工视觉','已检查','近似预览；屋型与整体密度仍可深化'),('用户审美 / 游戏客户端','待验收','没有执行 Minecraft 实机测试')]
contents.append(section(8,'检查结果与本轮修正',table(['项目','状态','范围'],checks)+'<p>首轮检查发现窗沿占到门口、树木与车辆占到路线。后续保留旧输出，修正入口保护范围；进一步检查发现 H02 过短接路段存在垂直重复坐标，当前改为从门外开始连续降阶，补回支撑。</p><details><summary>查看当前 NBT 哈希与分项记录</summary><code class="hash">'+mf['sha256']+'</code><pre>'+html.escape(json.dumps(vf,ensure_ascii=False,indent=2))+'</pre></details>'))
contents.append(section(9,'版本、流程与现有 Skill',table(['阶段','变化'],[('JapanTown01','风格研究：Freedom 系列目录与有限样本观察；没有整镇建造'),('J01','12 栋、道路、公交站与基础内饰；留下入口冲突负例'),('J02','修正窗沿、树木和车辆对路线的占用'),('J03','增加窗组差异、阳台、百叶、院落与商业前场'),('J04','补充高差庭院和地面植物承托；扩展检查'),('J05 · 当前','修正 H02 接路坡度与路径支撑，完整重导出、回读与预览')])+'<p>当前流程：恢复研究 → 原创空间与用途设定 → 冻结坐标及稳定 ID → HAF 0.4 交接计划 → 案例适配器写方块 → 最终 NBT 回读 → 修正冲突 → 世界导出 → 日夜与技术视图 → 游戏验收。</p><p>本轮沿用 <b>gafacraft-concept-design</b> 与 <b>gafacraft-architect</b>；前置资料来自 <b>gafacraft-ha-research</b> 的记录方式。<b>gafacraft-building-reference</b> 保持外部建筑 AI 六图资料包的独立用途。本轮没有新增个人 Skill，也没有训练模型权重。</p><p>版本分开记：基础工程脉络 HAF 0.4；研究整合 HAF05；日式小镇案例 J05。不会把新案例编号当作通用引擎升级。</p>'))
contents.append(section(10,'打开存档与下一步','<ol><li>解压 <b>JapanTown12_World_1.21.1.zip</b>，将其中世界文件夹放入 Minecraft 的 <code>saves</code>。</li><li>使用 Java 1.21.1 打开，默认创造模式；出生点 <code>14 65 -7</code>。原版方块，无需模组。</li><li>白天 <code>/time set day</code>；夜景 <code>/time set night</code>。首次加载等待游戏重算光照。</li></ol><p class="note">为了稳定样板，随机刻、昼夜循环和天气默认关闭。车辆、售货机与床为装饰。单独 NBT 是稀疏文件，建议优先使用独立世界存档。</p><h3>下一步的优先顺序</h3><ol><li><b>实机走街：</b>从公交站到咖啡店，再走坡上住宅；检查尺度、入口、楼梯和夜间亮度。</li><li><b>地块与体量随机：</b>固定同样的 12 栋功能配额，比较 3–5 个布局种子；测连续街墙、公共点可达性、退距与遮挡。</li><li><b>建筑家族扩充：</b>补更现代的住宅、L 形组合、错层和多种临街商店，降低共用基础体块的相似度。</li><li><b>石板路分支：</b>另做步行型老街，研究窄巷、连续檐口与庭院；保留这版道路小镇作对照。</li></ol>'))
short='12栋原创日式道路小镇，7住宅、2商业、3公共建筑，公交站，转折沥青主街，坡上庭院，克制木饰面和灰瓦，少量赤瓦青瓦，生活细节，低层功能空间全亮。'
long=short+' 以冻结的176×160格场地和稳定楼栋ID为约束，保留北侧2–3格高差、两条支路及入口全宽通行。阳台、百叶、商店雨棚与庭院边界按建筑用途分组；植物和墙段仅在允许位置按种子变化。家具优先表达主用途。四向相机同尺度，俯视严格垂直；剖面与爆炸图保持同源水平坐标。'
contents.append('<section><h2>研究来源与可带走的数据</h2><p>本轮基于前轮已记录的 Freedom 局部采样与城市视频观察继续原创，没有新增逐集完整观看声明，也未读取百度存档。</p><ul><li><a href="https://chatgpt.com/library?file_id=libfile_663d4d014de08191a97fdef972408368&account_id=personal">JapanTown01 风格研究</a></li><li><a href="https://www.youtube.com/watch?v=I40jEm-xIsU">Freedom · 原始参考链接</a></li><li><a href="https://www.bilibili.com/video/BV1wUktYAE2G/">《一年，一人，一城》· 原始参考链接</a></li><li><a href="https://chatgpt.com/library?file_id=libfile_a02e02ce0d4881918ecd59ccedcb81fa&account_id=personal">HAF05 历代研究整合</a></li></ul><button id="saveSpec">下载本版空间参数 JSON</button><details><summary>长短设计关键词</summary><h3>短关键词</h3><p>'+short+'</p><h3>长关键词</h3><p>'+long+'</p></details></section>')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f1e9;color:#243b37;font:16px/1.8 system-ui,-apple-system,"Noto Sans CJK SC",sans-serif}main{max-width:1160px;margin:auto;padding:38px 24px 80px}header{padding-top:15px}.eyebrow,.kicker{color:#718875;font-size:12px;font-weight:700;letter-spacing:.15em}h1{font-size:clamp(38px,6vw,76px);font-weight:650;line-height:1.13;letter-spacing:-.04em;margin:20px 0}h1 span{display:block;font-size:.48em;letter-spacing:.02em;margin-top:15px;color:#68806e}header>p{max-width:730px;color:#65736c;font-size:18px}h2{font-size:30px;line-height:1.3;margin:12px 0 24px}h3{font-size:19px;margin:18px 0 8px}p{margin:12px 0 18px}section{padding:45px 0;border-top:1px solid #d8ded2}nav{display:flex;gap:18px;overflow:auto;white-space:nowrap;margin:25px 0 40px;padding:10px 0;border-block:1px solid #d8ded2}a{color:#41776b;text-underline-offset:4px}.badges{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}.badges b{font-size:12px;border:1px solid #bcc8ba;border-radius:20px;padding:4px 13px;font-weight:500}figure{margin:22px 0 30px;background:#e4e8de;border-radius:12px;overflow:hidden;border:1px solid #dbe1d6}img{width:100%;height:auto;display:block}figcaption{padding:12px 16px;font-size:13px;color:#637166;background:#faf9f5}strong{color:#2f4941}.two{display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:start}.two figure{margin-top:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;padding:22px 0}.stats b{display:block;font-size:32px;font-weight:600}.stats span{font-size:13px;color:#6b7b71}.note{font-size:14px;color:#68796f;border-left:3px solid #bdc9b8;padding:5px 16px;background:#eaf0e7}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:540px;font-size:14px}th,td{padding:13px 14px;text-align:left;border-bottom:1px solid #dae0d4}th{background:#e4eadf}tr:nth-child(even){background:#f8f7f2}details{margin:22px 0;background:#ecf0e7;padding:15px;border-radius:9px}summary{cursor:pointer;font-weight:600}pre{overflow:auto;font-size:12px;max-height:420px;background:#e1e9dd;padding:18px}code{font-size:.88em;background:#e5eadf;padding:2px 6px;border-radius:3px}.hash{display:block;word-break:break-all;margin-top:20px}.map{background:#fffef8;padding:15px;border-radius:14px}.map svg{display:block;width:100%}button{border:0;border-radius:8px;background:#315e50;color:#fff;padding:13px 20px;font:inherit;cursor:pointer}footer{font-size:12px;color:#6d7e71;margin-top:35px}li{margin:9px 0}@media(max-width:650px){main{padding:22px 15px 50px}.two{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}h2{font-size:25px}section{padding:32px 0}figure{border-radius:8px}.stats b{font-size:28px}header>p{font-size:16px}}'''
nav='<nav>'+''.join(f'<a href="#s{i}">{t}</a>' for i,t in [(1,'完成内容'),(2,'布局'),(4,'日夜街景'),(5,'随机机制'),(6,'同源图纸'),(8,'验证'),(9,'历代变化'),(10,'下一步')])+'</nav>'
doc='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>日和町12栋 · 道路小镇 '+RUN+'</title><style>'+css+'</style></head><body><main>'+hero+nav+''.join(contents)+'<footer>日和町 / JapanTown12 · 原创研究案例 · '+RUN+' · 仅离线图片与技术数据，无重型三维预览。</footer></main><script id="case-data" type="application/json">'+json.dumps(spec,ensure_ascii=False).replace('</',r'<\/')+'</script><script>document.getElementById("saveSpec").onclick=()=>{const b=new Blob([document.getElementById("case-data").textContent],{type:"application/json"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download="JapanTown12_Design.json";a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};</script></body></html>'
